import sys
from collections import defaultdict, deque

def centroid_decomposition(tree, n):
    size = [1] * (n + 1)
    parent = [0] * (n + 1)

    def dfs(node, par):
        parent[node] = par
        for neighbor in tree[node]:
            if neighbor != par:
                size[node] += dfs(neighbor, node)
        return size[node]

    dfs(1, 0)

    def find_centroid(node, par, total_size):
        for neighbor in tree[node]:
            if neighbor != par and size[neighbor] > total_size // 2:
                return find_centroid(neighbor, node, total_size)
        return node

    centroids = []
    while n > 0:
        centroid = find_centroid(1, 0, n)
        centroids.append(centroid)
        n -= size[centroid]
        for neighbor in tree[centroid]:
            tree[neighbor].remove(centroid)
        size[centroid] = 0

    return centroids

def max_edges_covered(tree, n):
    centroids = centroid_decomposition(tree, n)
    max_edges = 0
    best_a, best_b, best_c = 0, 0, 0

    for centroid in centroids:
        distances = [-1] * (n + 1)
        queue = deque([centroid])
        distances[centroid] = 0

        while queue:
            node = queue.popleft()
            for neighbor in tree[node]:
                if distances[neighbor] == -1:
                    distances[neighbor] = distances[node] + 1
                    queue.append(neighbor)

        farthest_node = centroid
        for i in range(1, n + 1):
            if distances[i] > distances[farthest_node]:
                farthest_node = i

        distances = [-1] * (n + 1)
        queue = deque([farthest_node])
        distances[farthest_node] = 0

        while queue:
            node = queue.popleft()
            for neighbor in tree[node]:
                if distances[neighbor] == -1:
                    distances[neighbor] = distances[node] + 1
                    queue.append(neighbor)

        second_farthest_node = farthest_node
        for i in range(1, n + 1):
            if distances[i] > distances[second_farthest_node]:
                second_farthest_node = i

        diameter = distances[second_farthest_node]

        for i in range(1, n + 1):
            if distances[i] == diameter // 2:
                a = i
            elif distances[i] == (diameter + 1) // 2:
                b = i

        for i in range(1, n + 1):
            if distances[i] == (diameter + 2) // 2:
                c = i
                break

        covered_edges = sum(distances[i] != -1 for i in range(1, n + 1))

        if covered_edges > max_edges:
            max_edges = covered_edges
            best_a, best_b, best_c = a, b, c

    return max_edges, best_a, best_b, best_c

